#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT a;
    std::vector<int > S;
    template<typename REAL>
    REAL f(
        const REAL & x)
    {
        assert( std::binary_search(S.begin(), S.end(), x) );

        return x;    
    }
    heartlib(const std::vector<int > & S)
    {

        this->S = S;
        // a = f(2)
        a = f(DT(2));
    }
};

